export function getTranslatedShantuiMachineType(typeName: string, language: string = 'en'): string {
  const translations = shantuiMachineTypeTranslations[typeName];
  if (!translations) return typeName;
  return translations[language] || translations['en'] || typeName;
}

export function getTranslatedShantuiMachineSpecs(modelName: string, language: string = 'en'): string {
  const translations = shantuiMachineSpecsTranslations[modelName];
  if (!translations) return '';
  return translations[language] || translations['en'] || '';
}
